function plot(id,xd,yd,xt,yt,log=false){return window.BookCharts.frame(id,{x:d3.scaleLinear().domain(xd),y:(log?d3.scaleLog():d3.scaleLinear()).domain(yd).nice(),xLabel:xt,yLabel:yt});}
function curve(p,data,fx,fy,color=C.gold,dash=null){window.BookCharts.addSeries(p.node||p.svg.node(),data.map(d=>({x:fx(d),y:fy(d)})));p.svg.append('path').datum(data).attr('d',d3.line().x(d=>p.x(fx(d))).y(d=>p.y(fy(d)))).attr('fill','none').attr('stroke',color).attr('stroke-width',1.7).attr('stroke-dasharray',dash);}
function selected(p,x,y){p.svg.append('line').attr('x1',p.x(x)).attr('x2',p.x(x)).attr('y1',p.m.top).attr('y2',p.h-p.m.bottom).attr('stroke',C.muted).attr('stroke-dasharray','3 5');p.svg.append('circle').attr('cx',p.x(x)).attr('cy',p.y(y)).attr('r',4).attr('fill',C.gold);}
