 $('resolution-separation-value').textContent=fmt(shown,2)+'″';$('resolution-psf-value').textContent=fmt(s.psf,2)+'″';$('resolution-width').textContent=fmt(v.sigma);$('resolution-ratio').textContent=fmt(shown/v.sigma,2);$('resolution-peaks').textContent=v.doublePeaked?'两个峰':'一个峰';$('resolution-collected').textContent=fmt(v.collected*100,4)+'%';$('resolution-lost').textContent=fmt(v.lost*100,5)+'%';$('resolution-result').textContent=`连续剖面${v.doublePeaked?'有两个峰':'只有一个峰'}；本模型的临界分离为 ${fmt(v.threshold)}″。无限范围总通量为1；16个探测格现在按像素边界积分，±8″窗口收集 ${fmt(v.collected*100,4)}%。固定曝光色标，没有逐帧按最亮格重新归一。双峰条件仍只针对连续剖面，不等于有噪声时的检测。`;$('bench-readout').textContent=`d=${fmt(shown,2)}″ · ${v.doublePeaked?'双峰':'单峰'}`;stage.setAttribute('aria-valuenow',fmt(shown,2));stage.setAttribute('aria-valuetext',`分离${fmt(shown,2)}角秒，PSF宽度${fmt(s.psf,2)}角秒，${v.doublePeaked?'双峰':'单峰'}`);
 if(projection){for(const piece of ['sourceL','sourceR']){const sign=piece==='sourceL'?-1:1,[x,y]=projectShift(sign*(shown-.5)*7);stage.querySelectorAll(`[data-bench-piece="${piece}"]`).forEach(g=>g.setAttribute('transform',`translate(${x.toFixed(4)} ${y.toFixed(4)})`));}stage.querySelectorAll('[data-bench-pixel]').forEach(g=>{const I=v.pixels[+g.dataset.benchPixel],color=d3.interpolateRgb(window.BookTheme.color('#29414a'),window.BookTheme.color('#e4c389'))(Math.sqrt(I));g.querySelector('.iso-top')?.setAttribute('style','fill:'+color);});}
