 function syncButton(){const on=wantTour&&visible&&!reduced.matches;$('bench-tour').textContent=on?'暂停示范':'播放示范';$('bench-tour').setAttribute('aria-pressed',String(on));}
 function tick(now){const dt=last?Math.min(.05,(now-last)/1000):1/60;last=now;if(reduced.matches)wantTour=false;syncButton();if(wantTour&&!reduced.matches){clock+=dt;const targets=[3,1,5];s.separation=targets[Math.floor(clock/3.6)%3];$('resolution-separation').value=s.separation;}shown=reduced.matches?s.separation:shown+(s.separation-shown)*(1-Math.exp(-dt/.18));if(Math.abs(shown-s.separation)<.002)shown=s.separation;render();if(visible&&((wantTour&&!reduced.matches)||shown!==s.separation))frame=requestAnimationFrame(tick);else frame=0;}
