 $('resolution-separation').value=s.separation;$('resolution-psf').value=s.psf;$('resolution-separation').addEventListener('input',e=>steer(+e.target.value));$('resolution-psf').addEventListener('input',e=>{wantTour=false;s.psf=+e.target.value;save();render();run();});$('bench-tour').addEventListener('click',()=>{wantTour=!wantTour;if(reduced.matches)wantTour=false;run();});stage.addEventListener('keydown',e=>{let next=null;if(['ArrowLeft','ArrowDown'].includes(e.key))next=s.separation-.1;if(['ArrowRight','ArrowUp'].includes(e.key))next=s.separation+.1;if(e.key==='Home')next=.5;if(e.key==='End')next=6;if(next!==null){e.preventDefault();steer(next);}});
 let drag=null;stage.addEventListener('pointerdown',e=>{drag={x:e.clientX,start:s.separation};stage.setPointerCapture(e.pointerId);stage.focus();wantTour=false;run();});stage.addEventListener('pointermove',e=>{if(drag)steer(drag.start+(e.clientX-drag.x)/stage.clientWidth*5.5);});for(const name of ['pointerup','pointercancel'])stage.addEventListener(name,()=>{drag=null;});
 new IntersectionObserver(entries=>{visible=entries.at(-1).isIntersecting;run();},{threshold:0}).observe(stage);document.addEventListener('visibilitychange',()=>{if(document.hidden){visible=false;run();}else{const r=stage.getBoundingClientRect();visible=r.bottom>0&&r.top<innerHeight;run();}});reduced.addEventListener('change',()=>{if(reduced.matches){wantTour=false;shown=s.separation;render();}run();});
 Promise.all([fetch('assets/resolution-bench.svg').then(r=>{if(!r.ok)throw Error('bench');return r.text();}),fetch('assets/resolution-bench-projection.json').then(r=>r.json())]).then(([svg,meta])=>{stage.innerHTML=svg;projection=meta.P;render();}).catch(()=>{stage.dataset.fallback='true';});
