// Existing experiments also pause once their whole section leaves the viewport.
const animated=[...document.querySelectorAll('button[id$="-play"]')],roots=new Set(animated.map(b=>b.closest('.lab,.reading-section,.chapter-opening')||b.parentElement));
const pauseIn=root=>root.querySelectorAll('button[id$="-play"]').forEach(b=>{if(/^暂停/.test(b.textContent.trim()))b.click();});
if(roots.size){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)pauseIn(e.target);}));roots.forEach(r=>observer.observe(r));}
